    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            cin >> g[i][j];
        }
    }

    long long lo = g[0][0], hi = g[n - 1][n - 1];
    while (lo < hi) {
        long long mid = lo + (hi - lo) / 2, count = 0;
        int j = n - 1;
        for (int i = 0; i < n; i++) {
            while (j >= 0 && g[i][j] > mid) j--;
            count += j + 1;
        }
        if (count >= k) hi = mid;
        else lo = mid + 1;
    }
    cout << lo << "\n";

    return 0;
}

